// Task 편집 패널
import { useState, useEffect } from 'react';
import type { ProjectTask, Project } from '../../types/work';
import './TaskEditPanel.css';

interface TaskEditPanelProps {
  task: ProjectTask | null;
  projects: Project[];
  onSave: (task: ProjectTask) => Promise<void>;
  onComplete: (taskId: string) => Promise<void>;
  onUndoComplete: (taskId: string) => Promise<void>;
  onDelete: (taskId: string) => Promise<void>;
  onClose: () => void;
}

export default function TaskEditPanel({
  task,
  projects,
  onSave,
  onComplete,
  onUndoComplete,
  onDelete,
  onClose,
}: TaskEditPanelProps) {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [projectId, setProjectId] = useState<string | null>(null);
  const [startAt, setStartAt] = useState('');
  const [endAt, setEndAt] = useState('');
  const [dueAt, setDueAt] = useState('');
  const [isAllDay, setIsAllDay] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // 태스크 변경 시 폼 초기화
  useEffect(() => {
    if (task) {
      setTitle(task.title);
      setDescription(task.description || '');
      setProjectId(task.projectId);
      setStartAt(task.start_at ? formatDateTimeLocal(task.start_at) : '');
      setEndAt(task.end_at ? formatDateTimeLocal(task.end_at) : '');
      setDueAt(task.due_at ? formatDateTimeLocal(task.due_at) : '');
      setIsAllDay(task.is_all_day);
    }
  }, [task]);

  if (!task) return null;

  const isDone = task.status === 'DONE';

  // ISO 날짜를 datetime-local 형식으로 변환
  function formatDateTimeLocal(isoDate: string): string {
    if (!isoDate) return '';
    const date = new Date(isoDate);
    const tzOffset = date.getTimezoneOffset() * 60000;
    const localDate = new Date(date.getTime() - tzOffset);
    return localDate.toISOString().slice(0, 16);
  }

  // datetime-local 값을 ISO 문자열로 변환
  function toISOString(dateTimeLocal: string): string | null {
    if (!dateTimeLocal) return null;
    return new Date(dateTimeLocal).toISOString();
  }

  // 저장
  const handleSave = async () => {
    if (!title.trim() || isSaving) return;

    setIsSaving(true);
    try {
      await onSave({
        ...task,
        title: title.trim(),
        description: description.trim(),
        projectId,
        start_at: toISOString(startAt),
        end_at: toISOString(endAt),
        due_at: toISOString(dueAt),
        is_all_day: isAllDay,
        updated_at: Date.now(),
      });
    } catch (error) {
      console.error('Failed to save task:', error);
    } finally {
      setIsSaving(false);
    }
  };

  // 완료 토글
  const handleToggleComplete = async () => {
    try {
      if (isDone) {
        await onUndoComplete(task.id);
      } else {
        await onComplete(task.id);
      }
    } catch (error) {
      console.error('Failed to toggle task completion:', error);
    }
  };

  // 삭제
  const handleDelete = async () => {
    try {
      await onDelete(task.id);
      onClose();
    } catch (error) {
      console.error('Failed to delete task:', error);
    }
  };

  // 프로젝트 색상 가져오기
  const getProjectColor = (pid: string | null): string => {
    if (!pid) return '#64748b';
    const project = projects.find(p => p.id === pid);
    return project?.color || '#64748b';
  };

  return (
    <div className="task-edit-panel">
      <div className="panel-header">
        <div className="panel-title-wrapper">
          <span 
            className="project-indicator" 
            style={{ backgroundColor: getProjectColor(projectId) }}
          />
          <h3>태스크 편집</h3>
        </div>
        <button className="close-btn" onClick={onClose}>×</button>
      </div>

      <div className="panel-content">
        {/* 상태 표시 */}
        {isDone && (
          <div className="status-badge done">
            ✓ 완료됨 ({task.completed_at && new Date(task.completed_at).toLocaleDateString('ko-KR')})
          </div>
        )}

        {/* 제목 */}
        <div className="form-group">
          <label>제목</label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="태스크 제목"
          />
        </div>

        {/* 프로젝트 선택 */}
        <div className="form-group">
          <label>프로젝트</label>
          <select
            value={projectId || ''}
            onChange={(e) => setProjectId(e.target.value || null)}
          >
            <option value="">미분류</option>
            {projects.map((project) => (
              <option key={project.id} value={project.id}>
                {project.title}
              </option>
            ))}
          </select>
        </div>

        {/* 종일 여부 */}
        <div className="form-group checkbox-group">
          <label>
            <input
              type="checkbox"
              checked={isAllDay}
              onChange={(e) => setIsAllDay(e.target.checked)}
            />
            종일
          </label>
        </div>

        {/* 시작일 */}
        <div className="form-group">
          <label>시작일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && startAt ? startAt.slice(0, 10) : startAt}
            onChange={(e) => setStartAt(e.target.value)}
          />
        </div>

        {/* 종료일 */}
        <div className="form-group">
          <label>종료일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && endAt ? endAt.slice(0, 10) : endAt}
            onChange={(e) => setEndAt(e.target.value)}
          />
        </div>

        {/* 마감일 */}
        <div className="form-group">
          <label>마감일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && dueAt ? dueAt.slice(0, 10) : dueAt}
            onChange={(e) => setDueAt(e.target.value)}
          />
        </div>

        {/* 메모 */}
        <div className="form-group">
          <label>메모</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="태스크 설명 또는 메모..."
            rows={4}
          />
        </div>

        {/* 메타 정보 */}
        <div className="meta-info">
          <span>생성: {new Date(task.created_at).toLocaleDateString('ko-KR')}</span>
          <span>수정: {new Date(task.updated_at).toLocaleDateString('ko-KR')}</span>
        </div>
      </div>

      <div className="panel-footer">
        <button
          className={`complete-toggle-btn ${isDone ? 'done' : ''}`}
          onClick={handleToggleComplete}
        >
          {isDone ? '완료 취소' : '✓ 완료'}
        </button>
        <button
          className="delete-btn"
          onClick={() => setShowDeleteConfirm(true)}
        >
          삭제
        </button>
        <button
          className="save-btn"
          onClick={handleSave}
          disabled={!title.trim() || isSaving}
        >
          {isSaving ? '저장 중...' : '저장'}
        </button>
      </div>

      {/* 삭제 확인 다이얼로그 */}
      {showDeleteConfirm && (
        <div className="confirm-overlay">
          <div className="confirm-dialog">
            <h4>태스크 삭제</h4>
            <p>
              이 태스크와 하위 모든 투두가 삭제됩니다.
              <br />
              이 작업은 되돌릴 수 없습니다.
            </p>
            <div className="confirm-actions">
              <button
                className="cancel-btn"
                onClick={() => setShowDeleteConfirm(false)}
              >
                취소
              </button>
              <button
                className="confirm-delete-btn"
                onClick={handleDelete}
              >
                삭제
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
